                pesoDocumental = 0.6,
            )
        }
    }

    @Test
    fun `un peso de la mezcla encuestas-documental negativo es rechazado`() {
        assertThrows<PonderacionNegativaException> {
            configuracionConMezcla(pesoEncuestas = -0.4, pesoDocumental = 0.6)
        }
    }

    // =========================================================================
    // Helpers
    // =========================================================================

    private fun configuracionConPesosFactores(pesosFactores: Map<String, Double>): ConfiguracionPonderaciones =
        ConfiguracionPonderaciones(
            caracteristicas = pesosFactores.keys.map { factor ->
                Caracteristica(id = "$factor.1", nombre = "C-$factor", factor = factor, ponderacion = 1.0)
            },
            pesosFactores = pesosFactores,
            pesoEncuestas = 0.4,
            pesoDocumental = 0.6,
        )

    private fun configuracionConMezcla(pesoEncuestas: Double, pesoDocumental: Double): ConfiguracionPonderaciones =
        ConfiguracionPonderaciones(
            caracteristicas = listOf(Caracteristica(id = "1.1", nombre = "C1", factor = "F1", ponderacion = 1.0)),
            pesosFactores = mapOf("F1" to 1.0),
            pesoEncuestas = pesoEncuestas,
            pesoDocumental = pesoDocumental,
        )

    private fun resultadoConPromedio(promedio: Double?): ResultadoEncuestaPregunta =
        ResultadoEncuestaPregunta(
            programa = "EGSTI",
            periodo = "20261",
            codigoPregunta = "A2",
            caracteristica = "1.1",
            estamentos = setOf(TipoEstamento.ESTUDIANTE),
            promedio = promedio,
        )

    private fun respuestaConCalificacion(calificacion: Int): RespuestaEncuesta =
        RespuestaEncuesta(
            id = "R001",
            estamento = TipoEstamento.ESTUDIANTE,
            factor = "Infraestructura",
            calificacion = calificacion,
            periodo = "20261",
        )

    private fun estudianteConCohorte(cohorte: String): Estudiante =
        Estudiante(
            id = "EST-001",
            programa = "Ingeniería de Sistemas",
            facultad = "Ingeniería",
            cohorte = cohorte,
            estado = EstadoEstudiante.MATRICULADO,
        )

    private fun estudianteConPuntaje(puntaje: Int): Estudiante =
        Estudiante(
            id = "EST-001",
            programa = "Ingeniería de Sistemas",
            facultad = "Ingeniería",
            cohorte = "20211",
            estado = EstadoEstudiante.GRADUADO,
            puntajeSaberPro = puntaje,
        )
}

package com.example.sgva.application

import com.example.sgva.domain.EntidadDuplicadaException
import com.example.sgva.domain.ResultadoEncuestaPregunta
import com.example.sgva.domain.TipoEstamento
import com.example.sgva.usecases.ConsultarResultadoEncuestaPreguntaUseCase
import com.example.sgva.usecases.RegistrarResultadoEncuestaPreguntaUseCase
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import kotlin.test.assertEquals
import kotlin.test.assertNull

class GestionResultadosEncuestaPreguntaUseCaseTest {

    private val repositorio = RepositorioAcademicoFalso()
    private val registrar = RegistrarResultadoEncuestaPreguntaUseCase(repositorio)
    private val consultar = ConsultarResultadoEncuestaPreguntaUseCase(repositorio)

    @Test
    fun `registrar un resultado lo hace recuperable por su clave natural`() {
        val resultado = resultado(codigoPregunta = "A1")

        registrar.ejecutar(resultado)

        assertEquals(resultado, consultar.buscarPorClave("EGSTI", "20261", "A1"))
    }

    @Test
    fun `el listado devuelve los resultados en orden de registro`() {
        val primero = resultado(codigoPregunta = "A1")
        val segundo = resultado(codigoPregunta = "A2")

        registrar.ejecutar(primero)
        registrar.ejecutar(segundo)

        assertEquals(listOf(primero, segundo), consultar.listarTodos())
    }

    @Test
    fun `registrar una clave natural ya existente es rechazado sin sobrescribir el registro previo`() {
        val original = resultado(codigoPregunta = "A1", promedio = 4.5)
        registrar.ejecutar(original)

        assertThrows<EntidadDuplicadaException> {
            registrar.ejecutar(resultado(codigoPregunta = "A1", promedio = 2.0))
        }
        assertEquals(original, consultar.buscarPorClave("EGSTI", "20261", "A1"))
    }

    @Test
    fun `dos resultados del mismo periodo y programa con distinto codigo de pregunta no son duplicados`() {
        registrar.ejecutar(resultado(codigoPregunta = "A1"))

        registrar.ejecutar(resultado(codigoPregunta = "A2"))

        assertEquals(2, consultar.listarTodos().size)
    }

    @Test
    fun `consultar una clave inexistente devuelve null`() {
        assertNull(consultar.buscarPorClave("NO-EXISTE", "20261", "A1"))
    }

    @Test
    fun `el listado esta vacio cuando no hay resultados registrados`() {
        assertEquals(emptyList(), consultar.listarTodos())
    }

    private fun resultado(
        codigoPregunta: String,
        promedio: Double? = 4.0,
    ): ResultadoEncuestaPregunta = ResultadoEncuestaPregunta(
        programa = "EGSTI",
        periodo = "20261",
        codigoPregunta = codigoPregunta,
        caracteristica = "1.1",
        estamentos = setOf(TipoEstamento.ESTUDIANTE),
        promedio = promedio,
    )
}

package com.example.sgva.application

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.Docente
import com.example.sgva.domain.Estudiante
import com.example.sgva.domain.ResultadoEncuestaPregunta
import com.example.sgva.domain.RespuestaEncuesta

/**
 * Doble de prueba en memoria del puerto [AcademicDataRepository]. Permite
 * ejercitar los casos de uso sin depender del adaptador de infraestructura.
 * Pública (no `internal`) para poder exponerse como bean de Spring en las
 * pruebas de integración de `infrastructure.web` (`ConfiguracionCasosDeUsoDePrueba`).
 */
class RepositorioAcademicoFalso : AcademicDataRepository {

    private val estudiantes = LinkedHashMap<String, Estudiante>()
    private val docentes = LinkedHashMap<String, Docente>()
    private val respuestasEncuesta = LinkedHashMap<String, RespuestaEncuesta>()
    private val resultadosEncuestaPregunta = LinkedHashMap<String, ResultadoEncuestaPregunta>()

    override fun guardarEstudiante(estudiante: Estudiante): Estudiante {
        estudiantes[estudiante.id] = estudiante
        return estudiante
    }

    override fun buscarEstudiantePorId(id: String): Estudiante? = estudiantes[id]

    override fun listarEstudiantes(): List<Estudiante> = estudiantes.values.toList()

    override fun guardarDocente(docente: Docente): Docente {
        docentes[docente.id] = docente
        return docente
    }

    override fun buscarDocentePorId(id: String): Docente? = docentes[id]

    override fun listarDocentes(): List<Docente> = docentes.values.toList()

    override fun guardarRespuestaEncuesta(respuesta: RespuestaEncuesta): RespuestaEncuesta {
        respuestasEncuesta[respuesta.id] = respuesta
        return respuesta
    }

    override fun buscarRespuestaEncuestaPorId(id: String): RespuestaEncuesta? = respuestasEncuesta[id]

    override fun listarRespuestasEncuesta(): List<RespuestaEncuesta> = respuestasEncuesta.values.toList()

    override fun guardarResultadoEncuestaPregunta(resultado: ResultadoEncuestaPregunta): ResultadoEncuestaPregunta {
        resultadosEncuestaPregunta[claveDe(resultado.programa, resultado.periodo, resultado.codigoPregunta)] =
            resultado
        return resultado
    }

    override fun buscarResultadoEncuestaPregunta(
        programa: String,
        periodo: String,
        codigoPregunta: String,
    ): ResultadoEncuestaPregunta? = resultadosEncuestaPregunta[claveDe(programa, periodo, codigoPregunta)]

    override fun listarResultadosEncuestaPregunta(): List<ResultadoEncuestaPregunta> =
        resultadosEncuestaPregunta.values.toList()

    private fun claveDe(programa: String, periodo: String, codigoPregunta: String): String =
        "$programa|$periodo|$codigoPregunta"

    /** Vacía los cuatro almacenes; útil para reutilizar la misma instancia entre pruebas. */
    fun limpiar() {
        estudiantes.clear()
        docentes.clear()
        respuestasEncuesta.clear()
        resultadosEncuestaPregunta.clear()
    }
}

