import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import kotlin.test.assertEquals
import kotlin.test.assertNull
import kotlin.test.assertTrue

class CsvDocumentParserTest {

    private val parser = CsvDocumentParser()

    @Test
    fun `soporta solo archivos con extension csv`() {
        assertTrue(parser.soporta("datos_estudiantes.csv"))
        assertTrue(parser.soporta("RUTA/Datos.CSV"))
        assertTrue(!parser.soporta("datos.xlsx"))
    }

    @Test
    fun `extrae los estudiantes del fixture y trata la celda vacia de puntaje como null`() {
        val estudiantes = parser.extraerEstudiantes("datos_estudiantes_test.csv", fixture("datos_estudiantes_test.csv"))

        assertEquals(10, estudiantes.size)
        val primero = estudiantes.first()
        assertEquals("2021101", primero.id)
        assertEquals("20211", primero.cohorte)
        assertEquals(EstadoEstudiante.GRADUADO, primero.estado)
        assertEquals(210, primero.puntajeSaberPro)
        assertNull(estudiantes[2].puntajeSaberPro)
    }

    @Test
    fun `normaliza el periodo con guion de los docentes al formato AAAAS`() {
        val docentes = parser.extraerDocentes("datos_docentes_test.csv", fixture("datos_docentes_test.csv"))

        assertEquals(4, docentes.size)
        assertTrue(docentes.all { it.periodo == "20261" })
        assertTrue(docentes.all { it.programa == "EGSTI" })
        assertEquals(NivelFormacion.DOCTORADO, docentes.first().nivelFormacion)
        assertEquals(TipoDedicacion.MEDIO_TIEMPO, docentes.last().dedicacion)
    }

    @Test
    fun `extrae las respuestas de encuesta del fixture y normaliza el periodo con guion`() {
        val respuestas =
            parser.extraerRespuestasEncuestas("datos_encuestas_test.csv", fixture("datos_encuestas_test.csv"))

        assertEquals(5, respuestas.size)
        assertTrue(respuestas.all { it.periodo == "20261" })
        val primera = respuestas.first()
        assertEquals("R001", primera.id)
        assertEquals(TipoEstamento.ESTUDIANTE, primera.estamento)
        assertEquals("Plan de Estudios", primera.factor)
        assertEquals(5, primera.calificacion)
        assertEquals(TipoEstamento.EMPLEADOR, respuestas.last().estamento)
    }

    @Test
    fun `extrae los resultados de encuesta por pregunta del fixture, normaliza el periodo y trata N A como promedio ausente`() {
        val resultados = parser.extraerResultadosEncuestaPregunta(
            "datos_resultados_encuesta_pregunta_test.csv",
            fixture("datos_resultados_encuesta_pregunta_test.csv"),
        )

        assertEquals(4, resultados.size)
        assertTrue(resultados.all { it.periodo == "20261" })
        assertTrue(resultados.all { it.programa == "EGSTI" })

        val primero = resultados[0]
        assertEquals(setOf(TipoEstamento.ESTUDIANTE), primero.estamentos)
        assertEquals(4.5, primero.promedio)

        val segundo = resultados[1]
        assertEquals(setOf(TipoEstamento.ESTUDIANTE, TipoEstamento.PROFESOR), segundo.estamentos)

        val tercero = resultados[2]
        assertNull(tercero.promedio)

        val cuarto = resultados[3]
        assertEquals(
            setOf(TipoEstamento.DIRECTIVO, TipoEstamento.ADMINISTRATIVO, TipoEstamento.ALIADO_ESTRATEGICO),
            cuarto.estamentos,
        )
    }

    @Test
    fun `rechaza un resultado de encuesta por pregunta con promedio igual a 0`() {
        val csv = """
            programa,periodo,codigoPregunta,caracteristica,estamentos,promedio
            EGSTI,20261,A1,1.1,ESTUDIANTE,0
        """.trimIndent().toByteArray()

        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerResultadosEncuestaPregunta("datos.csv", csv)
        }
        assertTrue(error.message!!.contains("fila 2"))
    }

    @Test
    fun `rechaza un resultado de encuesta por pregunta con un estamento no reconocible`() {
        val csv = """
            programa,periodo,codigoPregunta,caracteristica,estamentos,promedio
            EGSTI,20261,A1,1.1,NO_EXISTE,4.5
        """.trimIndent().toByteArray()

        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerResultadosEncuestaPregunta("datos.csv", csv)
        }
        assertTrue(error.message!!.contains("estamentos"))
    }

    @Test
    fun `rechaza un csv al que le falta una columna obligatoria`() {
        val csv = "id,programa,facultad,estado\nE1,Sistemas,Ingeniería,MATRICULADO\n".toByteArray()

        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerEstudiantes("incompleto.csv", csv)
        }
        assertTrue(error.message!!.contains("cohorte"))
    }

    @Test
    fun `rechaza un csv con un enum no reconocible senalando la fila`() {
        val csv = buildString {
            append("id,programa,facultad,cohorte,estado,puntajeSaberPro\n")
            append("E1,Sistemas,Ingeniería,20231,MATRICULADO,\n")
            append("E2,Sistemas,Ingeniería,20231,EGRESADO,\n")
        }.toByteArray()

        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerEstudiantes("datos.csv", csv)
        }
        assertTrue(error.message!!.contains("fila 3"))
        assertTrue(error.message!!.contains("estado"))
    }

    private fun fixture(nombre: String): ByteArray =
        checkNotNull(javaClass.getResourceAsStream("/fixtures/$nombre")) { "falta el fixture $nombre" }
            .use { it.readBytes() }
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.EstadoEstudiante
import com.example.sgva.domain.FormatoArchivoInvalidoException
import com.example.sgva.domain.TipoEstamento
import org.apache.poi.xssf.usermodel.XSSFWorkbook
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import java.io.ByteArrayOutputStream
import kotlin.test.assertEquals
import kotlin.test.assertNull
import kotlin.test.assertTrue

class ExcelDocumentParserTest {

    private val parser = ExcelDocumentParser()

    @Test
    fun `soporta solo archivos con extension xlsx`() {
        assertTrue(parser.soporta("planta_docente.xlsx"))
        assertTrue(!parser.soporta("planta_docente.csv"))
    }

    @Test
    fun `extrae estudiantes de un libro con celdas numericas y de texto`() {
        val libro = xlsx(
            listOf("id", "programa", "facultad", "cohorte", "estado", "puntajeSaberPro"),
            listOf("2023106", "Ingeniería de Sistemas", "Ingeniería", "2023-1", "matriculado", ""),
            listOf("2021101", "Ingeniería de Sistemas", "Ingeniería", 20211.0, "GRADUADO", 210.0),
        )

        val estudiantes = parser.extraerEstudiantes("estudiantes.xlsx", libro)

        assertEquals(2, estudiantes.size)
        assertEquals("20231", estudiantes[0].cohorte)
        assertEquals(EstadoEstudiante.MATRICULADO, estudiantes[0].estado)
        assertNull(estudiantes[0].puntajeSaberPro)
        assertEquals("2021101", estudiantes[1].id)
        assertEquals(210, estudiantes[1].puntajeSaberPro)
    }

    @Test
    fun `ignora las filas totalmente vacias`() {
        val libro = xlsx(
            listOf("id", "programa", "facultad", "nivelFormacion", "dedicacion", "periodo"),
            listOf("D001", "EGSTI", "Ingenieria", "DOCTORADO", "TIEMPO_COMPLETO", "2026-1"),
            listOf("", "", "", "", "", ""),
        )

        val docentes = parser.extraerDocentes("docentes.xlsx", libro)

        assertEquals(1, docentes.size)
        assertEquals("20261", docentes.first().periodo)
        assertEquals("EGSTI", docentes.first().programa)
    }

    @Test
    fun `extrae respuestas de encuesta de un libro con celdas numericas y de texto`() {
        val libro = xlsx(
            listOf("id", "estamento", "factor", "calificacion", "periodo"),
            listOf("R001", "estudiante", "Infraestructura", 4.0, "2026-1"),
            listOf("R002", "PROFESOR", "Plan de Estudios", "5", "20261"),
        )

        val respuestas = parser.extraerRespuestasEncuestas("encuestas.xlsx", libro)

        assertEquals(2, respuestas.size)
        assertEquals(TipoEstamento.ESTUDIANTE, respuestas[0].estamento)
        assertEquals(4, respuestas[0].calificacion)
        assertEquals("20261", respuestas[0].periodo)
        assertEquals(TipoEstamento.PROFESOR, respuestas[1].estamento)
    }

    @Test
    fun `extrae resultados de encuesta por pregunta de un libro con celdas numericas y de texto`() {
        val libro = xlsx(
            listOf("programa", "periodo", "codigoPregunta", "caracteristica", "estamentos", "promedio"),
            listOf("EGSTI", "2026-1", "A1", "1.1", "ESTUDIANTE;PROFESOR", 4.5),
            listOf("EGSTI", "2026-1", "A2", "1.2", "DIRECTIVO", "N/A"),
        )

        val resultados = parser.extraerResultadosEncuestaPregunta("resultados.xlsx", libro)

        assertEquals(2, resultados.size)
        assertEquals("20261", resultados[0].periodo)
        assertEquals(setOf(TipoEstamento.ESTUDIANTE, TipoEstamento.PROFESOR), resultados[0].estamentos)
        assertEquals(4.5, resultados[0].promedio)
        assertNull(resultados[1].promedio)
    }

    @Test
    fun `rechaza un libro corrupto con una excepcion controlada`() {
        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerEstudiantes("corrupto.xlsx", "esto no es un xlsx".toByteArray())
        }
        assertTrue(error.message!!.contains("corrupto.xlsx"))
    }

    private fun xlsx(encabezados: List<String>, vararg filas: List<Any>): ByteArray =
        XSSFWorkbook().use { libro ->
            val hoja = libro.createSheet("datos")
            hoja.createRow(0).also { fila ->
                encabezados.forEachIndexed { i, titulo -> fila.createCell(i).setCellValue(titulo) }
            }
            filas.forEachIndexed { indiceFila, valores ->
                val fila = hoja.createRow(indiceFila + 1)
                valores.forEachIndexed { i, valor ->
                    val celda = fila.createCell(i)
                    when (valor) {
                        is Number -> celda.setCellValue(valor.toDouble())
                        else -> celda.setCellValue(valor.toString())
                    }
                }
            }
            ByteArrayOutputStream().use { salida ->
                libro.write(salida)
                salida.toByteArray()
            }
        }
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.FormatoArchivoInvalidoException
import org.apache.poi.ss.usermodel.Cell
import org.apache.poi.ss.usermodel.CellType
import org.apache.poi.ss.usermodel.Row
import org.apache.poi.xssf.usermodel.XSSFWorkbook
import org.springframework.stereotype.Component
import java.io.ByteArrayInputStream

/**
 * Adaptador de [com.example.sgva.domain.DocumentParserPort] para archivos `.xlsx`,
 * implementado sobre Apache POI (`DESIGN_SGVA.md` §4, adaptador «ApachePoiExcelParser»).
 *
 * Se procesa la primera hoja del libro: la primera fila es el encabezado y el
 * resto son datos. Las celdas numéricas se convierten a texto sin el `.0` que
 * añade Excel a los enteros; la normalización final la aplica [ParserDocumentalBase].
 */
@Component
internal class ExcelDocumentParser : ParserDocumentalBase() {

    override fun soporta(nombreArchivo: String): Boolean =
        nombreArchivo.substringAfterLast('.', "").lowercase() == "xlsx"

    override fun leerTabla(contenido: ByteArray): TablaCruda =
        XSSFWorkbook(ByteArrayInputStream(contenido)).use { libro ->
            if (libro.numberOfSheets == 0) {
                throw FormatoArchivoInvalidoException("El archivo Excel no contiene ninguna hoja.")
            }

            val filas = libro.getSheetAt(0).iterator().asSequence().toList()
            if (filas.isEmpty()) {
                throw FormatoArchivoInvalidoException("La primera hoja del archivo Excel está vacía.")
            }

            val encabezados = leerFila(filas.first()).map(String::trim)
            TablaCruda(
                encabezados = encabezados,
                filas = filas.drop(1)
                    .map { leerFila(it, encabezados.size) }
                    .filter { valores -> valores.any { it.isNotBlank() } },
            )
        }

    private fun leerFila(fila: Row, columnasMinimas: Int = 0): List<String> {
        val columnas = maxOf(fila.lastCellNum.toInt(), columnasMinimas)
        return (0 until columnas).map { indice ->
            valorComoTexto(fila.getCell(indice, Row.MissingCellPolicy.RETURN_BLANK_AS_NULL))
        }
    }

    private fun valorComoTexto(celda: Cell?): String = when {
        celda == null -> ""
        celda.cellType == CellType.STRING -> celda.stringCellValue.trim()
        celda.cellType == CellType.BOOLEAN -> celda.booleanCellValue.toString()
        celda.cellType == CellType.NUMERIC -> numeroComoTexto(celda.numericCellValue)
        celda.cellType == CellType.FORMULA -> when (celda.cachedFormulaResultType) {
            CellType.STRING -> celda.stringCellValue.trim()
            CellType.NUMERIC -> numeroComoTexto(celda.numericCellValue)
            CellType.BOOLEAN -> celda.booleanCellValue.toString()
            else -> ""
        }
        else -> ""
    }

    private fun numeroComoTexto(valor: Double): String =
        if (valor % 1.0 == 0.0) valor.toLong().toString() else valor.toString()
}

package com.example.sgva.infrastructure.web

import com.example.sgva.application.RepositorioAcademicoFalso
import com.example.sgva.domain.ResultadoEncuestaPregunta
import com.example.sgva.domain.TipoEstamento
import org.hamcrest.Matchers.containsString
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest
import org.springframework.context.annotation.Import
import org.springframework.http.MediaType
import org.springframework.mock.web.MockMultipartFile
import org.springframework.test.web.servlet.MockMvc
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders.multipart
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post
import org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath
import org.springframework.test.web.servlet.result.MockMvcResultMatchers.status
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * Pruebas de integración con `MockMvc` de [ResultadoEncuestaPreguntaController]:
 * mismo enfoque que [EncuestaControllerTest] y [DocenteControllerTest],
 * ejercitando controlador, casos de uso reales y [ManejadorGlobalDeErrores] juntos.
 */
@WebMvcTest(controllers = [ResultadoEncuestaPreguntaController::class])
@Import(ConfiguracionCasosDeUsoDePrueba::class)
class ResultadoEncuestaPreguntaControllerTest {

    @Autowired
    private lateinit var mockMvc: MockMvc

    @Autowired
    private lateinit var repositorio: RepositorioAcademicoFalso

    @BeforeEach
    fun limpiar() {
        repositorio.limpiar()
    }

    @Test
    fun `registrar un resultado valido devuelve 201 con el recurso creado`() {
        mockMvc.perform(
            post("/api/resultados-encuesta-pregunta")
                .contentType(MediaType.APPLICATION_JSON)
                .content(
                    """{"programa":"EGSTI","periodo":"20261","codigoPregunta":"A1",
                        "caracteristica":"1.1","estamentos":["ESTUDIANTE"],"promedio":4.5}
                    """.trimIndent(),
                ),
        )
            .andExpect(status().isCreated)
            .andExpect(jsonPath("$.codigoPregunta").value("A1"))
            .andExpect(jsonPath("$.promedio").value(4.5))

        assertEquals(1, repositorio.listarResultadosEncuestaPregunta().size)
    }

    @Test
    fun `registrar una clave natural ya existente devuelve 409 sin sobrescribir el original`() {
        repositorio.guardarResultadoEncuestaPregunta(resultado(codigoPregunta = "A1", promedio = 4.5))

        mockMvc.perform(
            post("/api/resultados-encuesta-pregunta")
                .contentType(MediaType.APPLICATION_JSON)
                .content(
                    """{"programa":"EGSTI","periodo":"20261","codigoPregunta":"A1",
                        "caracteristica":"1.1","estamentos":["PROFESOR"],"promedio":1.0}
                    """.trimIndent(),
                ),
        )
            .andExpect(status().isConflict)

        assertEquals(4.5, repositorio.buscarResultadoEncuestaPregunta("EGSTI", "20261", "A1")?.promedio)
    }

    @Test
    fun `registrar un promedio igual a 0 devuelve 400 con el mensaje de dominio`() {
        mockMvc.perform(
            post("/api/resultados-encuesta-pregunta")
                .contentType(MediaType.APPLICATION_JSON)
                .content(
                    """{"programa":"EGSTI","periodo":"20261","codigoPregunta":"A1",
                        "caracteristica":"1.1","estamentos":["ESTUDIANTE"],"promedio":0.0}
                    """.trimIndent(),
                ),
        )
            .andExpect(status().isBadRequest)

        assertTrue(repositorio.listarResultadosEncuestaPregunta().isEmpty())
    }

    @Test
    fun `listar devuelve los resultados registrados en orden de insercion`() {
        repositorio.guardarResultadoEncuestaPregunta(resultado(codigoPregunta = "A1"))
        repositorio.guardarResultadoEncuestaPregunta(resultado(codigoPregunta = "A2"))

        mockMvc.perform(get("/api/resultados-encuesta-pregunta"))
            .andExpect(status().isOk)
            .andExpect(jsonPath("$.length()").value(2))
            .andExpect(jsonPath("$[0].codigoPregunta").value("A1"))
            .andExpect(jsonPath("$[1].codigoPregunta").value("A2"))
    }

    @Test
    fun `listar filtra por programa y periodo`() {
        repositorio.guardarResultadoEncuestaPregunta(resultado(codigoPregunta = "A1", programa = "EGSTI"))
        repositorio.guardarResultadoEncuestaPregunta(resultado(codigoPregunta = "A2", programa = "OTRO"))

        mockMvc.perform(get("/api/resultados-encuesta-pregunta").param("programa", "EGSTI"))
            .andExpect(status().isOk)
            .andExpect(jsonPath("$.length()").value(1))
            .andExpect(jsonPath("$[0].programa").value("EGSTI"))
    }

    @Test
    fun `cargar un archivo csv valido registra los resultados y devuelve 201 con el resumen`() {
        val csv = """
            programa,periodo,codigoPregunta,caracteristica,estamentos,promedio
            EGSTI,20261,A1,1.1,ESTUDIANTE,4.5
            EGSTI,20261,A2,1.1,PROFESOR,N/A
        """.trimIndent()
        val archivo = MockMultipartFile("archivo", "resultados.csv", "text/csv", csv.toByteArray())

        mockMvc.perform(multipart("/api/resultados-encuesta-pregunta/archivos").file(archivo))
            .andExpect(status().isCreated)
            .andExpect(jsonPath("$.nombreArchivo").value("resultados.csv"))
            .andExpect(jsonPath("$.totalRegistrosLeidos").value(2))
            .andExpect(jsonPath("$.registrados").value(2))
            .andExpect(jsonPath("$.omitidos.length()").value(0))

        assertEquals(2, repositorio.listarResultadosEncuestaPregunta().size)
    }

    @Test
    fun `cargar un archivo con formato no soportado devuelve 400 sin registrar nada`() {
        val archivo = MockMultipartFile(
            "archivo",
            "resultados.txt",
            "text/plain",
            "programa\nEGSTI".toByteArray(),
        )

        mockMvc.perform(multipart("/api/resultados-encuesta-pregunta/archivos").file(archivo))
            .andExpect(status().isBadRequest)
            .andExpect(jsonPath("$.mensaje").value(containsString(".csv")))

        assertTrue(repositorio.listarResultadosEncuestaPregunta().isEmpty())
    }

    private fun resultado(
        codigoPregunta: String,
        programa: String = "EGSTI",
        promedio: Double? = 4.0,
    ): ResultadoEncuestaPregunta = ResultadoEncuestaPregunta(
        programa = programa,
        periodo = "20261",
        codigoPregunta = codigoPregunta,
        caracteristica = "1.1",
        estamentos = setOf(TipoEstamento.ESTUDIANTE),
        promedio = promedio,
    )
}

package com.example.sgva

import com.tngtech.archunit.core.importer.ClassFileImporter
import com.tngtech.archunit.lang.syntax.ArchRuleDefinition.classes
import com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses
import com.tngtech.archunit.library.GeneralCodingRules
import org.junit.jupiter.api.Test

class ArchitectureTest {

    private val classes = ClassFileImporter().importPackages("com.example.sgva")

    // =========================================================================
    // 1. REGLAS DE AISLAMIENTO Y DEPENDENCIA (CLEAN ARCHITECTURE)
    // =========================================================================
    @Test
    fun `el dominio no debe depender de capas externas ni frameworks`() {
        noClasses()
            .that().resideInAPackage("..domain..")
            .should().dependOnClassesThat()
            .resideInAnyPackage(
                "..usecases..",
                "..infrastructure..",
                "org.springframework..",
                "jakarta..",
                "javax..",
                "com.fasterxml.jackson.."
            )
            .check(classes)
    }

    @Test
    fun `los casos de uso no deben depender de infraestructura ni frameworks`() {
        noClasses()
            .that().resideInAPackage("..usecases..")
            .should().dependOnClassesThat()
            .resideInAnyPackage(
                "..infrastructure..",
                "org.springframework..",
                "jakarta..",
                "javax.."
            )
            .allowEmptyShould(true)
            .check(classes)
    }

    @Test
    fun `el dominio y los casos de uso no deben usar anotaciones de Spring`() {
        noClasses()
            .that().resideInAnyPackage("..domain..", "..usecases..")
            .should().beAnnotatedWith("org.springframework.stereotype.Component")
            .orShould().beAnnotatedWith("org.springframework.stereotype.Service")
            .orShould().beAnnotatedWith("org.springframework.beans.factory.annotation.Autowired")
            .check(classes)
    }

    // =========================================================================
    // 2. CONVENCIONES DE NOMENCLATURA
    // =========================================================================
    @Test
    fun `las clases de casos de uso deben finalizar en UseCase`() {
        classes()
            .that().resideInAPackage("..usecases..")
            .and().areNotInterfaces()
            .should().haveSimpleNameEndingWith("UseCase")
            .allowEmptyShould(true)
            .check(classes)
    }

    @Test
    fun `las interfaces de puerto en el dominio deben finalizar en Repository o Port`() {
        classes()
            .that().resideInAPackage("..domain..")
            .and().areInterfaces()
            .and().doNotHaveFullyQualifiedName("com.example.sgva.domain.DomainMarker")
            .should().haveSimpleNameEndingWith("Repository")
            .orShould().haveSimpleNameEndingWith("Port")
            .allowEmptyShould(true)
            .check(classes)
    }

    @Test
    fun `las excepciones de dominio deben finalizar en Exception`() {
        classes()
            .that().resideInAPackage("..domain..")
            .and().areAssignableTo(Throwable::class.java)
            .should().haveSimpleNameEndingWith("Exception")
            .allowEmptyShould(true)
            .check(classes)
    }

    @Test
    fun `los adaptadores rest en infraestructura deben finalizar en Controller`() {
        classes()
            .that().resideInAPackage("..infrastructure..")
            .and().areAnnotatedWith("org.springframework.web.bind.annotation.RestController")
            .should().haveSimpleNameEndingWith("Controller")
            .allowEmptyShould(true)
            .check(classes)
    }

    // =========================================================================
    // 3. BUENAS PRÁCTICAS DE CÓDIGO
    // =========================================================================
    @Test
    fun `no se debe usar la salida estandar ni de error directa (println)`() {
        NO_CLASSES_SHOULD_ACCESS_STANDARD_STREAMS.check(classes)
    }

    companion object {
        private val NO_CLASSES_SHOULD_ACCESS_STANDARD_STREAMS = GeneralCodingRules.NO_CLASSES_SHOULD_ACCESS_STANDARD_STREAMS
    }
}

package com.example.sgva.infrastructure.web

import com.example.sgva.domain.DatosInsuficientesException
import com.example.sgva.domain.DominioException
import com.example.sgva.domain.EntidadDuplicadaException
import org.springframework.http.HttpStatus
import org.springframework.http.ResponseEntity
import org.springframework.http.converter.HttpMessageNotReadableException
import org.springframework.web.bind.annotation.ExceptionHandler
import org.springframework.web.bind.annotation.RestControllerAdvice

/** Cuerpo de respuesta uniforme para los errores traducidos por [ManejadorGlobalDeErrores]. */
data class ErrorRespuesta(val mensaje: String)

/**
 * Traduce las excepciones de dominio (`DESIGN_SGVA.md` §0.1, §5) a respuestas
 * HTTP consistentes para todos los controladores REST. La validación de
 * negocio ya ocurrió en el dominio o en los casos de uso (constructores de
 * [com.example.sgva.domain.Estudiante]/[com.example.sgva.domain.Docente],
 * reglas de aplicación de los casos de uso); este adaptador solo traduce el
 * resultado a un código HTTP, no reimplementa reglas.
 */
@RestControllerAdvice
class ManejadorGlobalDeErrores {

    /** Identificador ya registrado: la solicitud es válida pero entra en conflicto con el estado actual. */
    @ExceptionHandler(EntidadDuplicadaException::class)
    fun manejarDuplicado(ex: EntidadDuplicadaException): ResponseEntity<ErrorRespuesta> =
        responder(HttpStatus.CONFLICT, ex.message)

    /** No hay datos suficientes para calcular el indicador solicitado. */
    @ExceptionHandler(DatosInsuficientesException::class)
    fun manejarDatosInsuficientes(ex: DatosInsuficientesException): ResponseEntity<ErrorRespuesta> =
        responder(HttpStatus.UNPROCESSABLE_CONTENT, ex.message)

    /** Resto de violaciones de reglas de negocio (formato inválido, campo vacío, archivo no soportado, etc.). */
    @ExceptionHandler(DominioException::class)
    fun manejarDominio(ex: DominioException): ResponseEntity<ErrorRespuesta> =
        responder(HttpStatus.BAD_REQUEST, ex.message)

    /**
     * El cuerpo JSON no pudo deserializarse. Si la causa raíz es una
     * [DominioException] —p. ej. el `init` de [com.example.sgva.domain.Estudiante]
     * rechazó el `puntajeSaberPro`— se conserva su mensaje; si es un problema de
     * formato ajeno al dominio (JSON corrupto, campo faltante), se responde con
     * un mensaje genérico.
     */
    @ExceptionHandler(HttpMessageNotReadableException::class)
    fun manejarCuerpoInvalido(ex: HttpMessageNotReadableException): ResponseEntity<ErrorRespuesta> {
        val causaDominio = generateSequence<Throwable>(ex) { it.cause }
            .filterIsInstance<DominioException>()
            .firstOrNull()
        return responder(HttpStatus.BAD_REQUEST, causaDominio?.message ?: "El cuerpo de la solicitud no es válido.")
    }

    private fun responder(estado: HttpStatus, mensaje: String?): ResponseEntity<ErrorRespuesta> =
        ResponseEntity.status(estado).body(ErrorRespuesta(mensaje ?: estado.reasonPhrase))
}

